mapper.update:
/* SmsXrayManageMapper.updateSmsXrayManage */
UPDATE  TB_CM_SMS_XRAY_WHITE
SET     APPR_FG     =   #{apprFg}
,       APPR_ID     =   #{apprId}
,       APPR_REASON =   #{apprReason}
,       MOD_DT      =   #{modDt}
,       MOD_ID      =   #{modId}
WHERE   USER_ID         =   #{userId}
AND     TEL_NO          =   #{telNo}
AND     SEND_URL        =   #{sendUrl}
AND     USE_START_DATE  =   #{useStartDate}

mapper.select:
/* SmsXrayManageMapper.getUrlBlockLogList */
SELECT A.MSG_BLOCK_ID , A.URL_TYPE , A.XRAY_ID , A.XRAY_URL , A.MSG_STATUS , A.MSG_CONTENT , SBPENC.D(A.CALLBACK) AS CALLBACK , A.S_OGN_CD , A.S_OGN_FG , A.S_USER_ID , TO_CHAR(TO_DATE(A.REG_DT, 'yyyymmddhh24miss'), 'yyyy-mm-dd hh24:mi:ss') AS REG_DT
FROM TB_CM_SMS_MESSAGE_BLOCK_XRAY A WHERE 1=1 AND A.REG_DT BETWEEN #{startDate}||'000000' AND #{endDate}||'235959'
AND A.URL_TYPE = #{urlType}
AND A.XRAY_URL LIKE '%' || #{chkUrl} || '%'
ORDER BY A.REG_DT
